//! Integration tests for querying a local icechunk store from SQL (feature `icechunk`).
//!
//! Drives the real `CREATE EXTERNAL TABLE ... STORED AS ZARR` path through
//! `ZarrTableFactory`, exactly as the CLI does, against `data/synthetic.icechunk`
//! (generated by `scripts/gen_synthetic_icechunk.py`; the M1 fixture:
//! `temperature[t,y,x] = t*100 + y*10 + x`, coords time(7)/lat(10)/lon(10)).
//!
//! Run: `cargo test --features icechunk --test integration_icechunk`
#![cfg(feature = "icechunk")]

use std::sync::Arc;

use datafusion::common::tree_node::{Transformed, TreeNode};
use datafusion::execution::session_state::SessionStateBuilder;
use datafusion::physical_plan::{collect, ExecutionPlan};
use datafusion::prelude::{SessionConfig, SessionContext};
use datafusion_proto::physical_plan::PhysicalExtensionCodec;
use zarr_datafusion::datasource::factory::ZarrTableFactory;
use zarr_datafusion::optimizer::{CountStatisticsRule, MinMaxStatisticsRule};
use zarr_datafusion::physical_plan::codec::ZarrPhysicalCodec;
use zarr_datafusion::physical_plan::zarr_exec::ZarrExec;
use zarr_datafusion::writer::ZarrFormatFactory;

const STORE: &str = "data/synthetic.icechunk";

/// A SessionContext wired like the CLI: ZARR table factory + the stat optimizer rules.
fn ctx() -> SessionContext {
    ctx_with_target(SessionConfig::new().target_partitions())
}

/// Like `ctx`, with scans targeting `n`-way parallelism.
fn ctx_with_target(n: usize) -> SessionContext {
    let state = SessionStateBuilder::new()
        .with_config(SessionConfig::new().with_target_partitions(n))
        .with_default_features()
        .with_table_factory("ZARR".to_string(), Arc::new(ZarrTableFactory) as _)
        .with_optimizer_rule(Arc::new(CountStatisticsRule::new()))
        .with_optimizer_rule(Arc::new(MinMaxStatisticsRule::new()))
        .build();
    SessionContext::new_with_state(state)
}

async fn register(ctx: &SessionContext) {
    ctx.sql(&format!(
        "CREATE EXTERNAL TABLE syn STORED AS ZARR LOCATION '{STORE}'"
    ))
    .await
    .expect("CREATE EXTERNAL TABLE over icechunk store")
    .collect()
    .await
    .expect("execute CREATE");
}

/// A single scalar cell from a one-row, one-column result.
async fn scalar_i64(ctx: &SessionContext, sql: &str) -> i64 {
    let batches = ctx.sql(sql).await.unwrap().collect().await.unwrap();
    let b = &batches[0];
    let col = b.column(0);
    // COUNT/aggregates may come back as Int64; coerce via display for robustness.
    let arr = arrow::compute::cast(col, &arrow::datatypes::DataType::Int64).unwrap();
    let arr = arr
        .as_any()
        .downcast_ref::<arrow::array::Int64Array>()
        .unwrap();
    arr.value(0)
}

#[tokio::test]
async fn schema_has_expected_columns() {
    let ctx = ctx();
    register(&ctx).await;

    let df = ctx.sql("SELECT * FROM syn LIMIT 0").await.unwrap();
    let names: Vec<String> = df
        .schema()
        .fields()
        .iter()
        .map(|f| f.name().clone())
        .collect();
    for expected in ["time", "lat", "lon", "temperature"] {
        assert!(
            names.iter().any(|n| n == expected),
            "expected column '{expected}' in {names:?}"
        );
    }
}

#[tokio::test]
async fn count_matches_cartesian_product() {
    let ctx = ctx();
    register(&ctx).await;
    // 7 time × 10 lat × 10 lon = 700 rows.
    assert_eq!(scalar_i64(&ctx, "SELECT COUNT(*) FROM syn").await, 700);
}

#[tokio::test]
async fn min_max_temperature() {
    let ctx = ctx();
    register(&ctx).await;
    // temperature = t*100 + y*10 + x, so min=0 (0,0,0), max=699 (6,9,9).
    let batches = ctx
        .sql("SELECT MIN(temperature) AS mn, MAX(temperature) AS mx FROM syn")
        .await
        .unwrap()
        .collect()
        .await
        .unwrap();
    let b = &batches[0];
    let mn = b
        .column(0)
        .as_any()
        .downcast_ref::<arrow::array::Float64Array>()
        .unwrap()
        .value(0);
    let mx = b
        .column(1)
        .as_any()
        .downcast_ref::<arrow::array::Float64Array>()
        .unwrap()
        .value(0);
    assert_eq!(mn, 0.0);
    assert_eq!(mx, 699.0);
}

#[tokio::test]
async fn value_exact_at_coordinate() {
    let ctx = ctx();
    register(&ctx).await;
    // Pin one cell by its COORDINATE VALUES (not indices): the generator writes
    // time = arange(7) (so time index 3 -> value 3), lat = linspace(-90,90,10)
    // (index 4 -> -10.0), lon = linspace(0,360,10,endpoint=False) (index 5 -> 180.0).
    // That cell is temperature[3,4,5] = 3*100 + 4*10 + 5 = 345.
    let batches = ctx
        .sql("SELECT temperature FROM syn WHERE time = 3 AND lat = -10.0 AND lon = 180.0")
        .await
        .unwrap()
        .collect()
        .await
        .unwrap();
    let total: usize = batches.iter().map(|b| b.num_rows()).sum();
    assert_eq!(total, 1, "expected exactly one matching row");
    let v = batches
        .iter()
        .find(|b| b.num_rows() > 0)
        .unwrap()
        .column(0)
        .as_any()
        .downcast_ref::<arrow::array::Float64Array>()
        .unwrap()
        .value(0);
    assert_eq!(v, 345.0);
}

fn scan_partitions(plan: &Arc<dyn ExecutionPlan>) -> Option<usize> {
    match plan.downcast_ref::<ZarrExec>() {
        Some(zarr) => Some(zarr.partitions().len()),
        None => plan.children().into_iter().find_map(scan_partitions),
    }
}

async fn partitions_for(ctx: &SessionContext, sql: &str) -> usize {
    let plan = ctx
        .sql(sql)
        .await
        .unwrap()
        .create_physical_plan()
        .await
        .unwrap();
    scan_partitions(&plan).expect("plan contains a ZarrExec")
}

#[tokio::test]
async fn scan_splits_time_chunks_across_partitions() {
    let ctx = ctx_with_target(4);
    register(&ctx).await;
    // 7 one-step time chunks over 4 partitions.
    assert_eq!(partitions_for(&ctx, "SELECT temperature FROM syn").await, 4);
    // The time filter resolves to steps 2..=5 on the head, which are split.
    assert_eq!(
        partitions_for(
            &ctx,
            "SELECT temperature FROM syn WHERE time >= 2 AND time <= 5"
        )
        .await,
        4
    );
}

#[tokio::test]
async fn partitioned_scan_is_value_transparent() {
    let queries = [
        "SELECT COUNT(temperature), SUM(temperature) FROM syn",
        "SELECT COUNT(temperature), SUM(temperature) FROM syn WHERE time >= 2 AND time <= 5",
        "SELECT COUNT(temperature), SUM(temperature) FROM syn WHERE time = 3 AND lat = -10.0",
        "SELECT time, SUM(temperature) FROM syn GROUP BY time ORDER BY time",
    ];
    let reference = ctx_with_target(1);
    register(&reference).await;
    for target in [3, 8] {
        let ctx = ctx_with_target(target);
        register(&ctx).await;
        for sql in queries {
            assert_eq!(
                formatted(&ctx, sql).await,
                formatted(&reference, sql).await,
                "{sql} at {target} partitions"
            );
        }
    }
}

async fn formatted(ctx: &SessionContext, sql: &str) -> String {
    let batches = ctx.sql(sql).await.unwrap().collect().await.unwrap();
    arrow::util::pretty::pretty_format_batches(&batches)
        .unwrap()
        .to_string()
}


/// `plan` with each scan sent through the codec, as a worker receives it:
/// without the store the head opened.
fn shipped(ctx: &SessionContext, plan: Arc<dyn ExecutionPlan>) -> Arc<dyn ExecutionPlan> {
    plan.transform_down(|node| {
        if node.downcast_ref::<ZarrExec>().is_none() {
            return Ok(Transformed::no(node));
        }
        let mut buf = Vec::new();
        ZarrPhysicalCodec.try_encode(node, &mut buf)?;
        let decoded = ZarrPhysicalCodec.try_decode(&buf, &[], &ctx.task_ctx())?;
        Ok(Transformed::yes(decoded))
    })
    .unwrap()
    .data
}

#[tokio::test]
async fn shipped_scan_reopens_the_icechunk_store() {
    let ctx = ctx();
    register(&ctx).await;
    for sql in [
        "SELECT COUNT(temperature), SUM(temperature) FROM syn",
        "SELECT temperature FROM syn WHERE time = 3 AND lat = -10.0 AND lon = 180.0",
    ] {
        let plan = ctx
            .sql(sql)
            .await
            .unwrap()
            .create_physical_plan()
            .await
            .unwrap();
        let want = collect(plan.clone(), ctx.task_ctx()).await.unwrap();
        let got = collect(shipped(&ctx, plan), ctx.task_ctx()).await.unwrap();
        assert_eq!(
            arrow::util::pretty::pretty_format_batches(&got)
                .unwrap()
                .to_string(),
            arrow::util::pretty::pretty_format_batches(&want)
                .unwrap()
                .to_string(),
            "{sql}"
        );
    }
}

#[tokio::test]
async fn copies_to_zarr_with_the_repository_s_coordinates() {
    let ctx = ctx();
    ctx.state_ref()
        .write()
        .register_file_format(Arc::new(ZarrFormatFactory), true)
        .unwrap();
    register(&ctx).await;
    let target = format!("{}/icechunk_copy.zarr", env!("CARGO_TARGET_TMPDIR"));
    let _ = std::fs::remove_dir_all(&target);
    let query = "SELECT lat, lon, avg(temperature) AS mean FROM syn \
                 WHERE lat >= 0 GROUP BY lat, lon";
    ctx.sql(&format!(
        "COPY ({query}) TO '{target}' STORED AS ZARR OPTIONS ('chunks' '5,5')"
    ))
    .await
    .unwrap()
    .collect()
    .await
    .unwrap();

    ctx.sql(&format!(
        "CREATE EXTERNAL TABLE copy STORED AS ZARR LOCATION '{target}'"
    ))
    .await
    .unwrap();
    let sorted = |sql: &str| format!("SELECT * FROM ({sql}) ORDER BY lat, lon");
    assert_eq!(
        formatted(&ctx, &sorted("SELECT lat, lon, mean FROM copy")).await,
        formatted(&ctx, &sorted(query)).await,
    );
}

// ==================== remote CIRA (network-gated) ====================

/// End-to-end read of the real CIRA FourCastNetv2 forecast from the public
/// ExtremeWeatherBench icechunk repo: anonymous GCS repo metadata + anonymous-S3
/// virtual HDF5 chunk decode, group addressing, and the mixed-dimensionality cube
/// (t2 is 4-D, resolved via native V3 `dimension_names`).
///
/// Ignored by default: it needs network access (anonymous GCS + S3) and reads a
/// few byte-ranges out of the 7.5 GB archival HDF5s. Run explicitly with:
///   cargo test --features icechunk --test integration_icechunk -- --ignored remote_cira
#[tokio::test]
#[ignore = "requires network: anonymous GCS + S3 reads of the public CIRA repo"]
async fn remote_cira_narrow_t2_read() {
    const CIRA: &str = "gs://extremeweatherbench/cira-icechunk";
    let ctx = ctx();
    ctx.sql(&format!(
        "CREATE EXTERNAL TABLE cira STORED AS ZARR LOCATION '{CIRA}' \
         OPTIONS ('group' 'FOUR_v200_GFS')"
    ))
    .await
    .expect("CREATE over remote icechunk repo")
    .collect()
    .await
    .expect("execute CREATE");

    // Narrow filter on all four of t2's coordinates -> a single-cell read (no
    // OOM despite the ~173-billion-row surface cube).
    let batches = ctx
        .sql(
            "SELECT t2 FROM cira \
             WHERE init_time = TIMESTAMP '2020-09-30T12:00:00Z' \
               AND lead_time = 0 AND latitude = 40.0 AND longitude = 280.0",
        )
        .await
        .unwrap()
        .collect()
        .await
        .unwrap();
    let total: usize = batches.iter().map(|b| b.num_rows()).sum();
    assert_eq!(total, 1, "expected exactly one matching cell");
    let k = batches
        .iter()
        .find(|b| b.num_rows() > 0)
        .unwrap()
        .column(0)
        .as_any()
        .downcast_ref::<arrow::array::Float32Array>()
        .unwrap()
        .value(0);
    // Surface air temperature in Kelvin: sane range for a mid-latitude land point.
    assert!(
        (230.0..=330.0).contains(&k),
        "t2 = {k} K is outside the plausible surface range"
    );
}
